-- GENERATED by `wfj generate` from data/gossip/gossip-35.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["3513d92ecca5beca"] = { "Bene, bene. Ora inchinatevi l'uno all'altro.", "." },
  ["35141cfe0a35241b"] = { "La ⟦Coldtooth Mine=Miniera di Dentefreddo⟧ si trova in territorio dell'⟦Horde=Orda⟧, sulle montagne a nord del ⟦Frostwolf Graveyard=Cimitero dei Lupi Bianchi⟧.\n\nÈ controllata dai coboldi.", "." },
  ["3514c29f2155f1ec"] = { "Una luce brillante appare dall'altra parte della stanza, poi scompare. Poi noti un altro raggio... e poi un altro ancora.\n\nSembrano mostrarti uno schema.", "." },
  ["3523f2ba1ff820df"] = { "Non ho mai detto che fossi qui per la tua redenzione, <sacerdote/sacerdotessa>. Sei qui per redimere me e gli innocenti assassinati mentre cercavano di fuggire da Stratholme.\n\nIl mio spirito e quello di chi è perito sono legati a questo luogo, condannati a rivivere senza fine le nostre tragiche morti.", "." },
  ["352ce9665091023c"] = { "Hai preso contatto con Ivus, Arcidruido?", "." },
  ["352d072c076b9e11"] = { "Immagino che tu abbia ragione.", "." },
  ["35311ea4dc143f93"] = { "⟦King Magni Bronzebeard=Re Magni Barbabronzea⟧ è un folle e un ciarlatano!", "." },
  ["35354bbba87651ba"] = { "Atten...TI!", "." },
  ["35388492d066caa3"] = { "Lasciali a me, {name}! Dammi solo il via e salirò in sella per attaccare il loro ponte!", "." },
  ["353f1731d2e1a7d2"] = { "Hai distrutto soltanto un'immagine, <sciocco/sciocca>. Ti darò la caccia fino alla fine dei giorni.", "." },
  ["354007764089d894"] = { "*GRRRR* *BAU* *BAU*", "." },
  ["354e013dd79ba637"] = { "Assicurati di leggere gli appunti nel mio diario, {name}. Ti saranno preziosissimi per superare le difese della torre.", "." },
  ["3558b060cfb6fb9a"] = { "Cosa sono le pietre del vincolo?", "." },
  ["356b7de4f3fd9ecd"] = { "%s lancia un grido acuto.", "." },
  ["35701b8901bcc2de"] = { "Kil'jaeden è la mia risposta.", "." },
  ["357332726278e9f3"] = { "Quanto ci vuole a raccogliere una manciata di erbacce?", "." },
  ["357d25890495886f"] = { "%s ruggisce di eccitazione mentre corre verso Volcor. Quando raggiunge il suo padrone, ⟦Grimclaw=Truceartiglio⟧ gli lecca la faccia.", "." },
  ["358346346b6e66c6"] = { "Eccomi di nuovo!", "." },
  ["358650fa38b3c15e"] = { "%s chiama la sua cavalcatura.", "." },
  ["3588311f0c9ceb6c"] = { "Allora... la verga. Vediamo di ripararla, che ne dici?", "." },
  ["35902dd362be6de8"] = { "Allontanati dal mio kodo, scherzo della natura!", "." },
  ["3592b96f5bbd3b84"] = { "Evocherò Eranikus quando mi verrà dato il segnale.", "." },
  ["35935aa4958196f7"] = { "Noi avere gancio da scuoiatura. Noi preso da Killian Hagey che insegna a noi come scuoiare prede. Tu avere bella pelle. Tu trovare lui su anello interno di ⟦Rogues' Quarter=Quartiere dei Ladri⟧.", "." },
  ["3597e67104d41da0"] = { "Il frammento dello scettro non c'è più! Il tuo amato Kalimdor diventerà presto una landa desolata. E naturalmente trasformerò i Regni Orientali in un vuoto di cenere senza vita...", "." },
  ["35980b0d41ceb708"] = { "Niente. I miei ordini erano di parlare con te e poi con Thrall. So solo che Thrall vuole salvare la tua principessa.", "." },
  ["359fccba10a0260b"] = { "Uno degli umani ha la chiave di questo congegno infernale. Eston, mi pare che abbiano detto si chiamasse.", "." },
  ["35a3a63144456aee"] = { "Grazie per l'interessamento, {class}, ma come vedi ho già tutte le bende di lino che l'⟦Alliance=Alleanza⟧ ritiene necessarie per prepararsi alla guerra di ⟦Ahn'Qiraj=Ahn'qiraj⟧. Questo però non ti impedisca di aiutare con le altre raccolte in corso qui.", "." },
  ["35a9f7a05ce1e03c"] = { "Indosserò la tua pelle come giacca da camera! I sigari? Dovrai strapparmeli dalle mie fredde mani morte... ehm... RAWR!!!!", "." },
  ["35b2567e2d859654"] = { "C'è un potente infernale di nome Kroshius a nord-est di questo accampamento. È per questo che Niby è qui. Kroshius è un infernale superiore: un infernale che è durato più del previsto. Vedi, <pivello/pivella>, un infernale si schianta sulla terra con grande intensità per servire il suo padrone, ma questa intensità svanisce in fretta. Una volta che le fiamme ardenti si sono spente, l'infernale si sbriciola.", "." },
  ["35b50a17ad58bbb2"] = { "A differenza della maggior parte degli ogre, io so a cosa serve un gabinetto: a infilarci la tua testa e tirare lo sciacquone. Ora sparisci.", "." },
  ["35c1c072d70f0412"] = { "Ti parlerei se avessi un odore migliore. Che ne dici di un'acqua di colonia? Magari un profumo?", "." },
  ["35cfa0c312e54d2e"] = { "Dov'è l'anziano Pozzodoro?", "." },
  ["35d048b5232efe99"] = { "Ragnaros vede tutto, mortale.", "." },
  ["35d5488df7421a57"] = { "Allora, <ragazzo/ragazza>, pensi di avere la stoffa per difendere l'⟦Alliance=Alleanza⟧ contro l'⟦Horde=Orda⟧ nella ⟦Alterac Valley=Valle d'Alterac⟧? Molto bene, allora vorrai parlare con il nostro ⟦Glordrum Steelbeard=Glordrum Barbacciaio⟧, qui a ⟦Ironforge=Forgiardente⟧. Lo troverai a studiare strategie sul tavolo da guerra nel Salone delle Armi.", "." },
  ["35d64bfc06cf6953"] = { "Ho perso la mia ⟦Blade of Vaulted Secrets=Lama dei Segreti Ignoti⟧. Puoi sostituirmela?", "." },
  ["35d84acdb5f9ca48"] = { "Ho ordinato qualche spedizione di nuovi profumi e acque di colonia dalla città. Quando le avrò disimballate, ripassa e le avrò in vendita.", "." },
  ["35d9c7df4f8011c5"] = { "Eroe, ho una questione urgente con il caporale Splithoof.", "." },
  ["35dcc299de151f70"] = { "Immagino sia vero. Io e il resto dei miei scelti appartenevamo a un ordine noto come Empyrean Blades. Eravamo la guardia personale del nostro precedente capo, lo Shal'nan. \r\n\nIn questi tempi incerti facciamo il possibile per aiutare a guidare la milizia cittadina dei Pacificatori, visto che siamo la cosa più vicina a soldati di professione rimasta su Zephras.", "." },
  ["35ded2e53b592928"] = { "Tempio di Atal'Hakkar", "." },
  ["35e0c6651914b4d5"] = { "Morirò, me lo sento!", "." },
  ["35e360b69f2033e6"] = { "Quindi hai conquistato un piccolo pezzo di terra. Una battuta d'arresto da poco! Il Flagello regna ancora qui!", "." },
  ["35e4e1e62fd9568a"] = { "Sei qui per imparare a usare una nuova arma, o solo per farmi perdere tempo?", "." },
  ["35e77149ee2a6dcd"] = { "L'anziano Soffiolungo si aggira per le strade di Stratholme.", "." },
})
